package com.arjunren.hospital.entity;
import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="patients")public class PatientProfile{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@OneToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="user_id",unique=true)private AppUser user;@Column(name="medical_record_number",nullable=false,unique=true,length=30)private String medicalRecordNumber;@Column(name="date_of_birth",nullable=false)private LocalDate dateOfBirth;@Column(length=30)private String phone;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt=Instant.now();protected PatientProfile(){}public PatientProfile(AppUser u,String n,LocalDate d,String p){user=u;medicalRecordNumber=n;dateOfBirth=d;phone=p;}public Long getId(){return id;}public AppUser getUser(){return user;}public String getMedicalRecordNumber(){return medicalRecordNumber;}public LocalDate getDateOfBirth(){return dateOfBirth;}public String getPhone(){return phone;}}

